package application

import (
	"context"
	"errors"
	"net/http"

	"github.com/google/uuid"
	"github.com/example/bank/pkg/httpx"
	"github.com/example/bank/pkg/authz"
)

type Handler struct {
	svc Service
}

func NewHandler(svc Service) *Handler {
	return &Handler{svc: svc}
}

func (h *Handler) Get(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	if err := authz.Require(ctx, "loan:read"); err != nil {
		httpx.WriteError(w, r, err)
		return
	}
	id, err := uuid.Parse(httpx.PathParam(r, "id"))
	if err != nil {
		httpx.WriteError(w, r, httpx.NewClientError("INVALID_ID", "id must be a uuid"))
		return
	}
	app, err := h.svc.Get(ctx, id)
	if err != nil {
		if errors.Is(err, ErrNotFound) {
			httpx.WriteError(w, r, httpx.NewClientError("NOT_FOUND", "application not found"))
			return
		}
		httpx.WriteError(w, r, err)
		return
	}
	httpx.WriteJSON(w, http.StatusOK, app)
}

package application

import (
	"context"
	"fmt"

	"github.com/google/uuid"
	"go.opentelemetry.io/otel"
)

var tracer = otel.Tracer("internal/loan/application")

type Service interface {
	Get(ctx context.Context, id uuid.UUID) (Application, error)
}

type service struct {
	repo Repository
}

func NewService(repo Repository) Service {
	return &service{repo: repo}
}

func (s *service) Get(ctx context.Context, id uuid.UUID) (Application, error) {
	ctx, span := tracer.Start(ctx, "application.Get")
	defer span.End()
	app, err := s.repo.GetByID(ctx, id)
	if err != nil {
		return Application{}, fmt.Errorf("application.Get: %w", err)
	}
	return app, nil
}

