package application

import (
	"context"
	"errors"
	"testing"

	"github.com/google/uuid"
	"github.com/stretchr/testify/require"
)

func TestService_Get(t *testing.T) {
	tests := []struct {
		name    string
		repo    Repository
		wantErr error
	}{
		{name: "happy path", repo: &fakeRepo{app: Application{}}, wantErr: nil},
		{name: "not found", repo: &fakeRepo{err: ErrNotFound}, wantErr: ErrNotFound},
		{name: "db error", repo: &fakeRepo{err: errors.New("db down")}, wantErr: nil /* placeholder */},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			s := NewService(tc.repo)
			_, err := s.Get(context.Background(), uuid.New())
			if tc.wantErr != nil {
				require.ErrorIs(t, err, tc.wantErr)
			}
		})
	}
}

type fakeRepo struct {
	app Application
	err error
}

func (f *fakeRepo) GetByID(ctx context.Context, id uuid.UUID) (Application, error) {
	return f.app, f.err
}
